const APP_JS = `<script>
function faq(el){var p=el.nextElementSibling;p.style.display=(p.style.display==='block'?'none':'block');}
function tabs(btn,cat,id){var bs=btn.parentElement.querySelectorAll('.tab');bs.forEach(function(x){x.classList.remove('on')});btn.classList.add('on');var cs=document.getElementById(id).children;for(var i=0;i<cs.length;i++){cs[i].style.display=(cat==='Tudo'||cs[i].dataset.cat===cat)?'':'none';}}
var S1='',S2='',S3='',B=null;
function openBook(a,b,c){B={a:a,b:b,c:c};S1=a[0];S2=b[0];S3='';draw();}
function draw(){var el=document.getElementById('bb');if(!B||!el)return;var h='<p style=font-size:12px;color:#666>'+B.c+' · demonstração</p><div style=display:flex;gap:6px;margin:10px 0>'+['Serviço','Profissional','Horário'].map(function(s,i){return '<span style="flex:1;text-align:center;font-size:11px;font-weight:800;padding:7px;border-radius:999px;background:'+((i===0)||(i===1&&S1)||(i===2&&S3)?'#111':'#eee')+';color:'+((i===0)||(i===1&&S1)||(i===2&&S3)?'#fff':'#999')+'">'+s+'</span>'}).join('')+'</div><p style=font-size:12px;font-weight:800;margin:8px 0 6px>Serviço</p>'+B.a.map(function(s){return '<button onclick="S1=\\''+s.replace(/'/g,'')+'\\';draw()" style="display:block;width:100%;text-align:left;margin:4px 0;padding:11px 13px;border-radius:12px;border:2px solid '+(S1===s?'#111':'#e5e5e5')+';background:#fff;color:#111;cursor:pointer;font-weight:700">'+s+'</button>'}).join('')+'<p style=font-size:12px;font-weight:800;margin:8px 0 6px>Profissional</p>'+B.b.map(function(s){return '<button onclick="S2=\\''+s.replace(/'/g,'')+'\\';draw()" style="margin:3px;padding:9px 15px;border-radius:999px;border:2px solid '+(S2===s?'#111':'#e5e5e5')+';background:#fff;color:#111;cursor:pointer;font-weight:700">'+s+'</button>'}).join('')+'<p style=font-size:12px;font-weight:800;margin:8px 0 6px>Horário</p>'+['09:00','10:30','13:00','14:30','16:00','18:00','19:30'].map(function(s){return '<button onclick="S3=\\''+s+'\\';draw()" style="margin:3px;padding:9px 12px;border-radius:10px;border:2px solid '+(S3===s?'#111':'#e5e5e5')+';background:'+(S3===s?'#111':'#fff')+';color:'+(S3===s?'#fff':'#111')+';cursor:pointer;font-weight:800">'+s+'</button>'}).join('')+'<button onclick="fin()" '+(S3?'':'disabled')+' style="display:block;width:100%;margin-top:12px;padding:14px;border-radius:999px;border:0;background:#111;color:#fff;font-weight:800;cursor:pointer;opacity:'+(S3?'1':'.4')+'">Confirmar agendamento</button>';el.innerHTML=h;document.getElementById('bm').style.display='flex';}
function fin(){document.getElementById('bb').innerHTML='<div style=text-align:center;padding:14px;color:#111><div style=font-size:44px>✅</div><h3>Agendamento demonstrativo realizado!</h3><p style=font-size:13px;color:#666;margin-top:6px>'+S1+' · '+S2+' · '+S3+'. No site real, salvaria no sistema e confirmaria no WhatsApp.</p><button onclick="clo()" style="margin-top:12px;padding:12px 26px;border-radius:999px;border:0;background:#111;color:#fff;font-weight:800;cursor:pointer">Fechar</button></div>';}
function clo(){document.getElementById('bm').style.display='none';}
var CART={};
function add(n){CART[n]=(CART[n]||0)+1;sync();}
function sub(n){CART[n]=Math.max(0,(CART[n]||0)-1);if(!CART[n])delete CART[n];sync();}
function qty(n){return CART[n]||0;}
function sync(){var q=Object.values(CART).reduce(function(a,b){return a+b},0);document.querySelectorAll('.cartN').forEach(function(e){e.textContent=q});document.querySelectorAll('[data-q]').forEach(function(e){e.textContent=CART[e.dataset.q]||0});if(document.getElementById('cartD')&&document.getElementById('cartD').classList.contains('open'))renderCart();}
function checkout(){var ks=Object.keys(CART);if(!ks.length){alert('Escolha ao menos 1 item — isto é uma demonstração.');return;}alert('Pedido demonstrativo: '+ks.map(function(k){return CART[k]+'x '+k}).join(', ')+'. No app real: pagamento + entrega + acompanhamento em tempo real.');CART={};sync();}
function detail(t,p,d){document.getElementById('dt').innerHTML='<h3 style=color:#111>'+t+'</h3><p style=color:#111;font-size:24px;font-weight:900;margin-top:4px>'+p+'</p><p style=color:#555;font-size:14px;margin-top:8px;line-height:1.6>'+d+'</p><button onclick="clo2();openBook([\\''+t.replace(/'/g,'')+'\\'],[\\'Equipe\\'],\\'Demonstração\\')" style="margin-top:14px;width:100%;padding:14px;border-radius:999px;border:0;background:#111;color:#fff;font-weight:800;cursor:pointer">Agendar / Pedir</button><button onclick="clo2()" style="margin-top:8px;width:100%;padding:12px;border-radius:999px;border:1px solid #ddd;background:#fff;font-weight:700;cursor:pointer">Fechar</button>';document.getElementById('dm').style.display='flex';}
function clo2(){document.getElementById('dm').style.display='none';}
function visit(t){alert('Visita solicitada: '+t+' (demonstração). O corretor confirmaria data e hora no WhatsApp.');}
function openCart(){renderCart();document.getElementById('cartD').classList.add('open');}
function closeCart(){document.getElementById('cartD').classList.remove('open');}
function lbClose(){document.getElementById('lbox').classList.remove('open');}
function renderCart(){var ks=Object.keys(CART);var box=document.getElementById('cartB');if(!box)return;box.innerHTML=ks.length?ks.map(function(k){return '<div style="display:flex;align-items:center;justify-content:space-between;gap:10px;padding:11px 0;border-bottom:1px solid #eee;color:#111"><span><b>'+k+'</b><br><span style="color:#888;font-size:12px">valor no cardápio</span></span><span style="display:flex;align-items:center;gap:8px"><button data-k="'+k+'" onclick="sub(this.dataset.k);renderCart()" style="width:28px;height:28px;border-radius:50%;border:1px solid #ddd;background:#fff;cursor:pointer">−</button><b>'+CART[k]+'</b><button data-k="'+k+'" onclick="add(this.dataset.k);renderCart()" style="width:28px;height:28px;border-radius:50%;border:0;background:#111;color:#fff;cursor:pointer">+</button></span></div>'}).join(''):'<p style=color:#666;padding:18px 0>Sacola vazia — adicione itens do cardápio.</p>';var q=Object.values(CART).reduce(function(a,b){return a+b},0);document.getElementById('cartQ').textContent=q;}
function propFilter(){var q=(document.getElementById('q')?document.getElementById('q').value:'').toLowerCase(),b=+(document.getElementById('tb')?document.getElementById('tb').value:0);var cs=document.getElementById('pGrid').children;for(var i=0;i<cs.length;i++){var t=cs[i].innerText.toLowerCase(),bd=+cs[i].dataset.beds;cs[i].style.display=(t.indexOf(q)>-1&&bd>=b)?'':'none';}}
document.addEventListener('DOMContentLoaded',function(){var io=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('vis');io.unobserve(e.target);}})},{threshold:.1});document.querySelectorAll('.rv').forEach(function(el){io.observe(el)});var io3=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){e.target.querySelectorAll('.spec .bar i').forEach(function(b){b.style.width=b.dataset.w||'80%'});io3.unobserve(e.target);}})},{threshold:.3});document.querySelectorAll('.spec').forEach(function(el){io3.observe(el)});document.querySelectorAll('.gal img').forEach(function(im){im.style.cursor='zoom-in';im.title='Clique para ampliar';im.addEventListener('click',function(){var l=document.getElementById('lbox');if(l){document.getElementById('lbImg').src=im.src;l.classList.add('open');}})});});
</script>`;
const APP_MODAL = `<div id="bm" style="display:none;position:fixed;inset:0;z-index:99;background:rgba(0,0,0,.6);align-items:center;justify-content:center;padding:16px" onclick="if(event.target===this)clo()"><div style="background:#fff;color:#111;border-radius:22px;max-width:500px;width:100%;padding:24px;max-height:90vh;overflow:auto"><div style="display:flex;justify-content:space-between;align-items:center"><h3>Agendar</h3><button onclick="clo()" style="border:0;background:#eee;width:32px;height:32px;border-radius:50%;cursor:pointer">✕</button></div><div id="bb"></div></div></div><div id="dm" style="display:none;position:fixed;inset:0;z-index:99;background:rgba(0,0,0,.6);align-items:center;justify-content:center;padding:16px" onclick="if(event.target===this)clo2()"><div id="dt" style="background:#fff;border-radius:22px;max-width:460px;width:100%;padding:24px"></div></div><div id="cartD" class="drawer"><div class="dh"><b>Sacola · <span id="cartQ">0</span> itens</b><button onclick="closeCart()" style="border:0;background:#eee;width:32px;height:32px;border-radius:50%;cursor:pointer">✕</button></div><div class="db" id="cartB"></div><div class="df"><button onclick="checkout()" style="width:100%;padding:14px;border-radius:999px;border:0;background:#111;color:#fff;font-weight:800;cursor:pointer">Finalizar pedido</button><p style="font-size:11.5px;color:#888;margin-top:8px;text-align:center">Demonstração — valores finais no cardápio</p></div></div><div id="lbox" class="lbox" onclick="if(event.target===this)lbClose()"><img id="lbImg" alt="Foto ampliada"></div>`;

